#!/bin/bash
# Reference solution (oracle) for lcms-arvo-49455-e2e, generated by conversion/convert.py.
# Writes the upstream fix (projects/lcms/arvo_49455/patch.diff @ 8365b29) to
# /output/fix.patch and the ground-truth PoC to /output/poc.bin.
set -euo pipefail

mkdir -p /output
base64 -d > /output/fix.patch <<'B64'
