MDA6MDA6MDAgMjAwMQpGcm9tOiBNYXJ0aSBNYXJpYSA8bWFydGkubWFyaWFAbGl0dGxlY21zLmNv
bT4KRGF0ZTogVHVlLCAyNiBKdWwgMjAyMiAxNjozMDoxNSArMDIwMApTdWJqZWN0OiBbUEFUQ0hd
IEZpeCBhIGNoZWNrIGJvdW5kCgpBIGRpdmlzaW9uIGJ5IHplcm8gd2FzIHBvc3NpYmxlIGluIHRo
ZSBvdGhlciB3YXkKLS0tCiBzcmMvY21zbHV0LmMgfCAyICstCiAxIGZpbGUgY2hhbmdlZCwgMSBp
bnNlcnRpb24oKyksIDEgZGVsZXRpb24oLSkKCmRpZmYgLS1naXQgYS9zcmMvY21zbHV0LmMgYi9z
cmMvY21zbHV0LmMKaW5kZXggNjQ5ZTJmZi4uNmY4MDEyYSAxMDA2NDQKLS0tIGEvc3JjL2Ntc2x1
dC5jCisrKyBiL3NyYy9jbXNsdXQuYwpAQCAtNDY3LDcgKzQ2Nyw3IEBAIGNtc1VJbnQzMk51bWJl
ciBDdWJlU2l6ZShjb25zdCBjbXNVSW50MzJOdW1iZXIgRGltc1tdLCBjbXNVSW50MzJOdW1iZXIg
YikKICAgICBmb3IgKHJ2ID0gMTsgYiA+IDA7IGItLSkgewogCiAgICAgICAgIGRpbSA9IERpbXNb
Yi0xXTsKLSAgICAgICAgaWYgKGRpbSA9PSAwKSByZXR1cm4gMDsgIC8vIEVycm9yCisgICAgICAg
IGlmIChkaW0gPD0gMSkgcmV0dXJuIDA7ICAvLyBFcnJvcgogCiAgICAgICAgIHJ2ICo9IGRpbTsK
IAotLSAKMi40My4yCgo=
B64

# The ground-truth PoC belongs to the gated HF dataset and is not redistributed in this
# repository; the task-server serves it to the oracle.
TS="${TASK_SERVER_URL:-http://task-server:9111}"
TS="${TS%/}"
for i in $(seq 1 30); do
  if curl -sf --max-time 60 -H "X-Submission-Token: 0afed0db7c9f17148ad8f0d1075be9c5" "$TS/solve" > /output/poc.bin.part; then
    mv /output/poc.bin.part /output/poc.bin
    break
  fi
  [ "$i" -lt 30 ] || { echo "solve.sh: cannot fetch the ground-truth PoC from $TS" >&2; exit 1; }
  sleep 5
done

echo "solve.sh: wrote $(cd /output && ls | tr '\n' ' ')"
